                    continue
                matched = False
                for reason in reasons:
                    if p.lower() == reason.lower() or reason.lower() in p.lower() or p.lower() in reason.lower():
                        counts[colname][reason] += 1; matched = True; break
                if not matched:
                    p2 = re.sub(r'\(.*?\)','',p).strip()
                    for reason in reasons:
                        if p2.lower() == reason.lower() or reason.lower() in p2.lower() or p2.lower() in reason.lower():
                            counts[colname][reason] += 1; matched = True; break
                    if not matched:
                        counts[colname][p] += 1
